#!/usr/bin/env python3\nimport re, sys\nfrom collections import Counter, defaultdict\n\nif len(sys.argv)!=2:\n    raise SystemExit('usage: analyze_p52a_log.py uzuy_log.txt')\nlines=open(sys.argv[1],encoding='utf-8',errors='replace').read().splitlines()\npatterns={\n 'wrapper': re.compile(r'\[NSC:P52A\] UJ_WRAPPER phase=(pre|post).*?char=(\d+).*?mode=(\d+).*?action=(\d+)'),\n 'state': re.compile(r'\[NSC:P52A\] UJ_STATE phase=(pre|post).*?char=(\d+).*?mode=(\d+).*?action=(\d+)'),\n 'sptype': re.compile(r'\[NSC:P52A\] SPTYPE_CTRL phase=(pre|post).*?char=(\d+).*?mode=(\d+).*?action=(\d+)'),\n 'play': re.compile(r'\[NSC:P50A\] PLAY_ACTION .*?char=(\d+).*?index=(\d+).*?ret=(-?\d+)'),\n 'ougi_caller': re.compile(r'\[NSC:P50A\] OUGI_CALLER .*?char=(\d+).*?mode=(\d+)'),\n 'ougi_core': re.compile(r'\[NSC:P50A\] OUGI_CORE .*?char=(\d+).*?mode=(\d+)'),\n}\nby=defaultdict(Counter)\nseq=defaultdict(list)\nfor ln in lines:\n    for kind,rx in patterns.items():\n        m=rx.search(ln)\n        if not m: continue\n        if kind=='play':\n            ch=int(m.group(1)); idx=int(m.group(2)); ret=int(m.group(3));\n            by[ch][f'play_{idx}']+=1; seq[ch].append((kind,idx,ret))\n        elif kind in ('ougi_caller','ougi_core'):\n            ch=int(m.group(1)); mode=int(m.group(2)); by[ch][f'{kind}_mode{mode}']+=1\n        else:\n            phase=m.group(1); ch=int(m.group(2)); mode=int(m.group(3)); action=int(m.group(4))\n            by[ch][f'{kind}_{phase}_mode{mode}']+=1\n            if phase=='pre': seq[ch].append((kind,mode,action))\nfor ch in sorted(by):\n    print(f'CHAR {ch}')\n    for k,v in sorted(by[ch].items()): print(f'  {k}: {v}')\n    print('  sequence:', ' -> '.join(str(x) for x in seq[ch][:80]))\nif not by: print('NO P52/P50 UJ TRACE MARKERS FOUND')\n